// Case 3.22 step 1 — Run the POS Purchase Payment Propagation batch.
// Enqueues a Veevart POS batch and verifies the AsyncApexJob was accepted.
// Class name + namespace confirmed against org im696-tucson (Tooling API):
//   Auctifera.POSPurchasePaymentPropagationBatch (Auctifera-only; no vnfp copy).
//   Live run confirmed its no-arg constructor is global (job reached Completed).
// This proves ENQUEUE only — batch execution is async (no completion wait).
class VerifyException extends Exception {}

// PM-editable: batch chunk size passed to Database.executeBatch.
final Integer BATCH_SCOPE = 200;

// Enqueue the batch. A non-global / non-visible class fails to COMPILE here,
// which the runner surfaces as result.success=false (step FAILED).
Id jobId = Database.executeBatch(new Auctifera.POSPurchasePaymentPropagationBatch(), BATCH_SCOPE);
System.debug(LoggingLevel.INFO, '[3.22] POSPurchasePaymentPropagationBatch enqueued jobId=' + jobId);

// VERIFY enqueue success — the AsyncApexJob row must exist and be in an
// accepted state. Throw so a failed enqueue reports the step FAILED.
List<AsyncApexJob> jobs = [
    SELECT Id, Status, ApexClass.Name
    FROM AsyncApexJob
    WHERE Id = :jobId
    LIMIT 1
];
if (jobs.isEmpty()) {
    throw new VerifyException('[3.22] verify failed: no AsyncApexJob for POSPurchasePaymentPropagationBatch jobId=' + jobId);
}
Set<String> ACCEPTED = new Set<String>{ 'Holding', 'Queued', 'Preparing', 'Processing', 'Completed' };
if (!ACCEPTED.contains(jobs[0].Status)) {
    throw new VerifyException('[3.22] verify failed: POSPurchasePaymentPropagationBatch job in unexpected state ' + jobs[0].Status);
}
System.debug(LoggingLevel.INFO, '[3.22] verify OK — POSPurchasePaymentPropagationBatch job ' + jobs[0].Id + ' status=' + jobs[0].Status + ' class=' + jobs[0].ApexClass.Name);
